function isKoreanText(value: string): boolean {
  return /[\p{Script=Hangul}]/u.test(value);
}

function resolveTokenLanguageCode(
  surface: string,
  fallbackLanguageCode?: string | null,
  tokenLanguageCode?: string | null,
): string | null {
  const normalizedTokenLanguage = tokenLanguageCode?.trim().toLowerCase();
  if (normalizedTokenLanguage) {
    return normalizedTokenLanguage;
  }

  if (isKoreanText(surface)) {
    return "ko";
  }

  if (/[\p{Script=Hiragana}\p{Script=Katakana}]/u.test(surface)) {
    return "ja";
  }

  if (/[\p{Script=Cyrillic}]/u.test(surface)) {
    return "ru";
  }

  if (/[\p{Script=Hebrew}]/u.test(surface)) {
    return "he";
  }

  if (/[\p{Script=Arabic}]/u.test(surface)) {
    return "ar";
  }

  if (/[\p{Script=Han}]/u.test(surface)) {
    const normalizedFallback = fallbackLanguageCode?.trim().toLowerCase().split("-", 1)[0];
    return normalizedFallback === "ja" || normalizedFallback === "zh" ? normalizedFallback : "zh";
  }

  if (/[A-Za-z]/u.test(surface)) {
    const normalizedFallback = fallbackLanguageCode?.trim().toLowerCase().split("-", 1)[0];
    return normalizedFallback === "en" || normalizedFallback === "yo" || normalizedFallback === "no" || normalizedFallback === "sv" || normalizedFallback === "fi"
      ? normalizedFallback
      : "en";
  }

  const normalizedFallback = fallbackLanguageCode?.trim().toLowerCase();
  return normalizedFallback?.split("-", 1)[0] || null;
}

function splitKoreanParticleChain(surface: string): string[] {
  const trimmed = surface.trim();
  if (!trimmed || !isKoreanText(trimmed)) {
    return [];
  }

  const parts: string[] = [];
  let remaining = trimmed;

  while (remaining.length > 1) {
    const suffix = koreanParticleSuffixes.find((candidate) => remaining.length > candidate.length && remaining.endsWith(candidate));
    if (!suffix) {
      break;
    }

    parts.unshift(suffix);
    remaining = remaining.slice(0, -suffix.length);
  }

  if (!parts.length) {
    return [];
  }

  return [remaining, ...parts];
}

function buildTokenReadingParts(
  token: TokenResult,
  languageCode?: string | null,
  pronunciationOverride?: string | null,
  readingOverride?: string | null,
  japaneseReadingDisplayMode: JapaneseReadingDisplayMode = "romaji",
): TokenReadingPart[] {
  const surface = token.surface_form ?? "";
  if (!surface) {
    return [];
  }

  const isJapanese = languageCode?.toLowerCase().startsWith("ja");
  const japaneseKana = isJapanese && japaneseReadingDisplayMode === "furigana" && hasKanji(surface)
    ? toHiragana(token.furigana?.trim() || (isJapaneseKanaOnly(token.pronunciation ?? "") ? token.pronunciation ?? "" : ""))
    : "";
  const reading = japaneseReadingDisplayMode === "furigana" && isJapanese ? japaneseKana : normalizeDisplayReading(
    readingOverride?.trim() ||
      token.romanization?.trim() ||
      pronunciationOverride?.trim() ||
      token.pronunciation?.trim() ||
      (languageCode?.startsWith("ko") ? surface : ""),
  );

  if (languageCode?.startsWith("ru") || isRussianText(surface)) {
    if (!reading) {
      return [];
    }

    const russianParts = splitRussianTransliterationIntoParts(reading);
    if (russianParts.length > 1) {
      const russianSurfaceParts = splitRussianCyrillicIntoParts(surface, russianParts.length);
      return russianParts.map((part, index) => ({
        surface: russianSurfaceParts[index] ?? surface,
        text: part,
        kind: "generic",
        gloss: null,
      }));
    }

    return [{ surface, text: reading, kind: "generic", gloss: null }];
  }

  if (languageCode?.startsWith("ko") || isKoreanText(surface)) {
    const koreanParts = splitKoreanParticleChain(surface);
    if (koreanParts.length > 1) {
      return koreanParts.map((part, index) => ({
        surface: part,
        text: normalizeDisplayReading(part),
        kind: index === 0 ? "stem" : "particle",
        gloss: index === 0 ? null : koreanParticleGlosses[part] ?? null,
      }));
    }
  }

  if (!reading) {
    return [];
  }

  const displayReading = languageCode?.startsWith("ja") && japaneseReadingDisplayMode === "furigana"
    ? finalizeJapaneseRomaji(reading).replace(/\s+/gu, "")
    : reading;

  return [{ surface, text: displayReading, kind: "generic", gloss: null }];
}

function getLexiconTraceSource(entry: LexiconEntryRecord | null, resolutionSource?: LexiconLookupResponse["resolution_source"] | null): string {
  if (!entry) {
    return "No lexicon metadata.";
  }

  const resolutionLabel =
    resolutionSource === "google_translate_cache"
      ? "Google Translate (cached)"
      : resolutionSource === "google_translate_live"
        ? "Google Translate (live)"
        : null;
  const parts = [resolutionLabel, entry.source_name?.trim(), entry.source_path?.trim(), entry.note?.trim()].filter(
    (part): part is string => Boolean(part),
  );
  return parts.length ? parts.join(" Â· ") : "No lexicon metadata.";
}

function formatLexiconMatchConfidence(
  matchConfidence?: LexiconLookupResponse["match_confidence"] | null,
  matchedTerm?: LexiconLookupResponse["matched_term"] | null,
): string | null {
  if (typeof matchConfidence !== "number" || !Number.isFinite(matchConfidence)) {
    return null;
  }

  const percent = Math.max(0, Math.min(100, Math.round(matchConfidence * 100)));
  if (matchedTerm) {
    return `Match confidence: ${percent}% (${matchedTerm})`;
  }
  return `Match confidence: ${percent}%`;
}

type LexiconSelectionState = "matched" | "ambiguous" | "unmatched";

type LexiconSelection = {
  entry: LexiconEntryRecord | null;
  state: LexiconSelectionState;
};

function normalizeLexiconComparisonValue(value: string | null | undefined): string {
  return normalizeDisplayReading(value).replace(/\s+/gu, "").toLocaleLowerCase();
}

function isJapaneseKanaOnly(value: string): boolean {
  return /^[\p{Script=Hiragana}\p{Script=Katakana}ー・]+$/u.test(value.trim());
}

function selectLexiconEntryForToken(
  token: TokenResult,
  response: LexiconLookupResponse | null,
  languageCode: string | null | undefined,
): LexiconSelection {
  const entries = response?.entries ?? [];
  if (!entries.length) {
    return { entry: null, state: "unmatched" };
  }

  if (!languageCode?.toLowerCase().startsWith("ja")) {
    return { entry: entries[0], state: "matched" };
  }

  const surface = token.surface_form.trim();
  const exactSurfaceEntries = entries.filter((entry) => entry.surface_form.trim() === surface);
  const tokenReading = normalizeLexiconComparisonValue(token.romanization ?? token.pronunciation);
  const readingMatches = tokenReading
    ? exactSurfaceEntries.filter((entry) => {
        const entryReading = normalizeLexiconComparisonValue(entry.pronunciation ?? entry.pinyin);
        return !entryReading || entryReading === tokenReading;
      })
    : exactSurfaceEntries;

  if (readingMatches.length === 1) {
    return { entry: readingMatches[0], state: "matched" };
  }

  if (readingMatches.length > 1) {
    const distinctMeanings = new Set(readingMatches.map((entry) => entry.definition?.trim() ?? ""));
    return distinctMeanings.size === 1
      ? { entry: readingMatches[0], state: "matched" }
      : { entry: null, state: "ambiguous" };
  }

  // A kana-only surface such as は must not inherit a kanji homograph such as 歯.
  // A lemma match is safe only when the visible token itself carries kanji evidence.
  const lemma = token.lemma?.trim() ?? "";
  const lemmaEntries = lemma && !isJapaneseKanaOnly(surface)
    ? entries.filter((entry) => entry.surface_form.trim() === lemma)
    : [];
  if (lemmaEntries.length === 1) {
    return { entry: lemmaEntries[0], state: "matched" };
  }

  return { entry: null, state: entries.length > 1 ? "ambiguous" : "unmatched" };
}

