function isCjkToken(value: string): boolean {
  return /[\u3400-\u4dbf\u4e00-\u9fff]/.test(value);
}

function isSentencePunctuation(value: string): boolean {
  const trimmed = value.trim();
  return trimmed.length === 0 || /^[\p{P}\p{S}\s]+$/u.test(trimmed);
}

function countReadableCharacters(value: string): number {
  return Array.from(value).filter((character) => !isSentencePunctuation(character)).length;
}

function countReadableTokenMetrics(sentences: SentenceResult[] | null | undefined): { words: number; characters: number } {
  let words = 0;
  let characters = 0;

  for (const sentence of sentences ?? []) {
    for (const token of sentence.tokens ?? []) {
      if (isSentencePunctuation(token.surface_form)) {
        continue;
      }
      words += 1;
      characters += countReadableCharacters(token.surface_form);
    }
  }

  return { words, characters };
}

function estimateReaderEtaSeconds(
  metrics: { words: number; characters: number },
  profileSummary: LearningProfileSummary | null,
): number | null {
  const secondsPerWord = profileSummary?.average_seconds_per_word ?? null;
  if (secondsPerWord != null && metrics.words > 0) {
    return metrics.words * secondsPerWord;
  }

  const secondsPerCharacter = profileSummary?.average_seconds_per_character ?? null;
  if (secondsPerCharacter != null && metrics.characters > 0) {
    return metrics.characters * secondsPerCharacter;
  }

  return null;
}

function formatEstimatedDuration(seconds: number | null): string {
  if (seconds == null || !Number.isFinite(seconds) || seconds <= 0) {
    return "â€”";
  }

  return `~${formatElapsed(Math.max(1, Math.round(seconds)))}`;
}

function formatReaderEstimatedDuration(seconds: number | null): string {
  if (seconds == null || !Number.isFinite(seconds) || seconds <= 0) {
    return "Unavailable";
  }

  return `~${formatElapsed(Math.max(1, Math.round(seconds)))}`;
}

function useReaderCarouselInteractions(carouselRef: { current: HTMLDivElement | null }, enabled = true): void {
  const dragStateRef = useRef<{
    pointerId: number;
    startX: number;
    startScrollLeft: number;
    dragged: boolean;
  } | null>(null);
  const suppressClickRef = useRef(false);

  useEffect(() => {
    const element = carouselRef.current;
    if (!enabled || !element) {
      return;
    }

    const handleWheel = (event: WheelEvent) => {
      if (element.scrollWidth <= element.clientWidth) {
        return;
      }

      const delta = Math.abs(event.deltaX) > Math.abs(event.deltaY) ? event.deltaX : event.deltaY;
      const maxScrollLeft = element.scrollWidth - element.clientWidth;
      const canScroll = delta < 0 ? element.scrollLeft > 0 : element.scrollLeft < maxScrollLeft;
      if (!delta || !canScroll) {
        return;
      }

      event.preventDefault();
      element.scrollLeft = Math.max(0, Math.min(maxScrollLeft, element.scrollLeft + delta));
    };

    const handlePointerDown = (event: PointerEvent) => {
      if (event.pointerType !== "mouse" || event.button !== 0 || element.scrollWidth <= element.clientWidth) {
        return;
      }

      dragStateRef.current = {
        pointerId: event.pointerId,
        startX: event.clientX,
        startScrollLeft: element.scrollLeft,
        dragged: false,
      };
      element.setPointerCapture(event.pointerId);
    };

    const handlePointerMove = (event: PointerEvent) => {
      const dragState = dragStateRef.current;
      if (!dragState || dragState.pointerId !== event.pointerId) {
        return;
      }

      const deltaX = event.clientX - dragState.startX;
      if (!dragState.dragged && Math.abs(deltaX) < 4) {
        return;
      }

      dragState.dragged = true;
      suppressClickRef.current = true;
      element.classList.add("is-dragging");
      event.preventDefault();
      element.scrollLeft = dragState.startScrollLeft - deltaX;
    };

    const releasePointer = (event: PointerEvent) => {
      const dragState = dragStateRef.current;
      if (!dragState || dragState.pointerId !== event.pointerId) {
        return;
      }

      dragStateRef.current = null;
      element.classList.remove("is-dragging");
      if (element.hasPointerCapture(event.pointerId)) {
        element.releasePointerCapture(event.pointerId);
      }
      if (event.type === "pointercancel") {
        suppressClickRef.current = false;
      } else if (suppressClickRef.current) {
        window.setTimeout(() => {
          suppressClickRef.current = false;
        }, 0);
      }
    };

    const handleClick = (event: MouseEvent) => {
      if (!suppressClickRef.current) {
        return;
      }

      suppressClickRef.current = false;
      event.preventDefault();
      event.stopPropagation();
    };

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") {
        return;
      }

      const items = Array.from(element.children).filter((child): child is HTMLElement => child instanceof HTMLElement);
      if (items.length === 0 || element.scrollWidth <= element.clientWidth) {
        return;
      }

      const direction = event.key === "ArrowRight" ? 1 : -1;
      const currentScrollLeft = element.scrollLeft;
      const targetItem = direction > 0
        ? items.find((item) => item.offsetLeft > currentScrollLeft + 8)
        : [...items].reverse().find((item) => item.offsetLeft < currentScrollLeft - 8);
      if (!targetItem) {
        return;
      }

      event.preventDefault();
      element.scrollTo({ left: targetItem.offsetLeft, behavior: "smooth" });
    };

    element.addEventListener("wheel", handleWheel, { passive: false });
    element.addEventListener("pointerdown", handlePointerDown);
    element.addEventListener("pointermove", handlePointerMove);
    element.addEventListener("pointerup", releasePointer);
    element.addEventListener("pointercancel", releasePointer);
    element.addEventListener("click", handleClick, true);
    element.addEventListener("keydown", handleKeyDown);

    return () => {
      element.removeEventListener("wheel", handleWheel);
      element.removeEventListener("pointerdown", handlePointerDown);
      element.removeEventListener("pointermove", handlePointerMove);
      element.removeEventListener("pointerup", releasePointer);
      element.removeEventListener("pointercancel", releasePointer);
      element.removeEventListener("click", handleClick, true);
      element.removeEventListener("keydown", handleKeyDown);
      element.classList.remove("is-dragging");
      dragStateRef.current = null;
    };
  }, [carouselRef, enabled]);
}

function formatLevelTag(value: string | number | null | undefined): string {
  const text = String(value ?? "").trim();
  if (!text) {
    return "â€”";
  }

  const normalized = text.replace(/^HSK\s*/i, "").trim();
  if (/^\d+(?:\.\d+)?$/.test(normalized)) {
    return `HSK ${normalized}`;
  }

  if (/^HSK\s+\d+(?:\.\d+)?$/i.test(text)) {
    return text.replace(/\s+/g, " ").replace(/^hsk/i, "HSK");
  }

  return text;
}
